sql:
SELECT DISTINCTROW [Sample_Env].*, [Sample_Admin].*
FROM (Sample_Env INNER JOIN Sample_SU ON [Sample_Env].PlotNumber = [Sample_SU].PlotNumber) INNER JOIN Sample_Admin ON [Sample_Env].PlotNumber = [Sample_Admin].Plot
WHERE ((([Sample_SU].PlotNumber) Is Not Null));

SELECT *
FROM USysMasterSiteUnitList;
UNION SELECT *
FROM USysUserSiteUnitList;

SELECT *
FROM USysMasterSiteUnitList;
UNION SELECT *
FROM USysUserSiteUnitList;

SELECT Code, ScientificName, LifeForm, EnglishName, Codetype
FROM USysAllSpecs
Where CodeType <> 's';
UNION SELECT Code, ScientificName, LifeForm, EnglishName, CodeType
FROM USysUserSpp
Where CodeType <> 's';

SELECT DISTINCTROW [Sample_Audit].*
FROM Sample_Audit
ORDER BY EditWhen;

SELECT DISTINCTROW ID, PlotNumber, Species, Cover1, Cover2, Cover3, TotalA, HeightA, Cover4, Cover5, Cover5a, Cover5b, Cover5c, TotalB, HeightB, Collected
FROM Sample_Veg
WHERE ((([Cover1]) Is Not Null)) OR ((([Cover2]) Is Not Null)) OR ((([Cover3]) Is Not Null)) OR ((([TotalA]) Is Not Null)) OR ((([Cover4]) Is Not Null)) OR ((([Cover5]) Is Not Null)) OR ((([TotalB]) Is Not Null)) OR (((Cover5a) Is Not Null)) OR (((Cover5b) Is Not Null)) OR (((Cover5c) Is Not Null));

SELECT DISTINCTROW ID, PlotNumber, Species, Cover4, Cover5, Cover5a, Cover5b, Cover5c, TotalB, Collected
FROM Sample_Veg
WHERE ((([Cover4]) Is Not Null)) OR ((([Cover5]) Is Not Null)) OR ((([TotalB]) Is Not Null)) OR (((Cover5a) Is Not Null)) OR (((Cover5b) Is Not Null)) OR (((Cover5c) Is Not Null));

SELECT DISTINCTROW ID, PlotNumber, Species, Cover6, Height6, Collected
FROM Sample_Veg
WHERE ((Cover6 Is Not Null));

SELECT DISTINCTROW ID, PlotNumber, Species, Cover7, Cover8, Cover9, Collected
FROM Sample_Veg
WHERE (((Cover7) Is Not Null)) OR (((Cover8) Is Not Null)) OR (((Cover9) Is Not Null));
